import org.eclipse.jface.text.StyledString;
import org.eclipse.jdt.core.IJavaElement;

// This mock class simulates the behavior of org.eclipse.jface.text.TextMessages
// and is required for the example to be self-contained and compile.
class TextMessages {
    public static StyledString markLTR(StyledString s) { return s; }
    public static StyledString markJavaElementLabelLTR(StyledString s) { return s; }
}

public class JavaElementLabels {
    public static StyledString getStyledElementLabel(IJavaElement element, long flags) {
        StyledString result= new StyledString();
        // Assume getElementLabel populates result
        return TextMessages.markLTR(result);
    }
}

